        .map(|slot| {
            let mut preimage = seed.to_vec();
            preimage.append(&mut int_to_bytes8(slot.as_u64()));
            let seed = hash(&preimage);
            self.compute_proposer_index(indices, &seed, spec)
        })
        .collect()
}

